<template><div class="os-page"><Card><template #title>AI Workflow Planner</template><template #content><Textarea v-model="request" rows="5" class="w-full" placeholder="مثال: كل يوم الساعة 8 ابحث عن وظائف Django Remote مناسبة لي وأرسل أفضل 5"/><Button class="mt-3" label="Generate Workflow" icon="pi pi-sparkles" :loading="loading" @click="plan"/><Message v-if="error" severity="error" class="mt-3">{{error}}</Message><div v-if="result" class="mt-4"><Message severity="success">{{result.explanation}}</Message><DataTable :value="result.nodes" class="mt-3"><Column field="type" header="Node"/><Column field="label" header="Label"/></DataTable></div></template></Card></div></template><script setup>import{ref}from'vue';import Card from'primevue/card';import Textarea from'primevue/textarea';import Button from'primevue/button';import Message from'primevue/message';import DataTable from'primevue/datatable';import Column from'primevue/column';import{aiAgentApi}from'@/services/osDomains';const request=ref(''),loading=ref(false),error=ref(''),result=ref(null);const plan=async()=>{if(!request.value.trim())return;loading.value=true;error.value='';try{result.value=await aiAgentApi.plan({request:request.value})}catch(e){error.value=e?.response?.data?.detail||e?.response?.data?.error||'Unable to create plan'}finally{loading.value=false}}</script><style scoped>.os-page{padding:1rem}.w-full{width:100%}</style>